            let _ = m1.insert(a).remove(b).count(v);
            let _ = Multiset::<i64>::singleton(a).count(v);
            let _ = Multiset::<i64>::singleton(b).count(v);

            // Key fact: a and b are both in m
            s.to_multiset_ensures();
